const fs = require('node:fs')
const path = require('node:path')

// Explicit module-scope dynamic imports allow Next to preload SSR themes.
// Generate from the same inventory as next.config so new themes remain automatic.
function writeThemeRegistry(themes) {
  const file = path.join(__dirname, '../../themes/themeLayouts.js')
  const content = [
    '// Generated by lib/build/themeRegistry.js. Add theme directories, not entries here.',
    "import dynamic from 'next/dynamic'",
    "import withLayouts from './withLayouts'",
    '',
    'export const themeLayouts = {',
    themes
      .slice()
      .sort()
      .map(
        name =>
          `  ${JSON.stringify(name)}: dynamic(() => import(${JSON.stringify('./' + name)}).then(withLayouts))`
      )
      .join(',\n'),
    '}',
    ''
  ].join('\n')
  if (!fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== content)
    fs.writeFileSync(file, content)
}
module.exports = { writeThemeRegistry }
